public readonly struct Vector2
{
    public double X { get; }
    public double Y { get; }

    public Vector2(double x, double y) => (X, Y) = (x, y);

    // Бинарные операторы
    public static Vector2 operator +(Vector2 a, Vector2 b) => new(a.X + b.X, a.Y + b.Y);
    public static Vector2 operator -(Vector2 a, Vector2 b) => new(a.X - b.X, a.Y - b.Y);
    public static Vector2 operator *(Vector2 a, double scalar) => new(a.X * scalar, a.Y * scalar);
    public static Vector2 operator *(double scalar, Vector2 a) => a * scalar; // commutative
    public static Vector2 operator /(Vector2 a, double scalar) => new(a.X / scalar, a.Y / scalar);

    // Унарные операторы
    public static Vector2 operator -(Vector2 a) => new(-a.X, -a.Y);
    public static Vector2 operator ++(Vector2 a) => a + new Vector2(1, 1);
    public static Vector2 operator --(Vector2 a) => a - new Vector2(1, 1);

    public override string ToString() => $"({X}, {Y})";
}

// Использование
var v1 = new Vector2(1, 2);
var v2 = new Vector2(3, 4);
var v3 = v1 + v2;        // (4, 6)
var v4 = v1 * 2.5;       // (2.5, 5)
var v5 = -v1;            // (-1, -2)

public readonly struct Version : IComparable<Version>, IEquatable<Version>
{
    public int Major { get; }
    public int Minor { get; }
    public int Patch { get; }

    public Version(int major, int minor, int patch) => (Major, Minor, Patch) = (major, minor, patch);

    // Обязательно парами: ==/!=, </>, <=/>=
    public static bool operator ==(Version a, Version b) => a.Equals(b);
    public static bool operator !=(Version a, Version b) => !a.Equals(b);
    public static bool operator <(Version a, Version b) => a.CompareTo(b) < 0;
    public static bool operator >(Version a, Version b) => a.CompareTo(b) > 0;
    public static bool operator <=(Version a, Version b) => a.CompareTo(b) <= 0;
    public static bool operator >=(Version a, Version b) => a.CompareTo(b) >= 0;

    public int CompareTo(Version other)
    {
        var c = Major.CompareTo(other.Major);
        if (c != 0) return c;
        c = Minor.CompareTo(other.Minor);
        if (c != 0) return c;
        return Patch.CompareTo(other.Patch);
    }

    public bool Equals(Version other) => Major == other.Major && Minor == other.Minor && Patch == other.Patch;
    public override bool Equals(object? obj) => obj is Version v && Equals(v);
    public override int GetHashCode() => HashCode.Combine(Major, Minor, Patch);
}

public readonly struct Celsius
{
    public double Degrees { get; }
    public Celsius(double degrees) => Degrees = degrees;

    // Implicit: безопасное, не теряет данных
    public static implicit operator Celsius(double degrees) => new(degrees);
    public static implicit operator double(Celsius c) => c.Degrees;

    // Explicit: может терять данные или быть неочевидным
    public static explicit operator Fahrenheit(Celsius c) => new(c.Degrees * 9 / 5 + 32);
    public static explicit operator Celsius(Fahrenheit f) => new((f.Degrees - 32) * 5 / 9);
}

