public class Money
{
    public decimal Amount { get; }
    public string Currency { get; }

    public Money(decimal amount, string currency) => (Amount, Currency) = (amount, currency);

    // Для классов операторы должны быть static
    public static Money operator +(Money a, Money b)
    {
        if (a.Currency != b.Currency) throw new InvalidOperationException("Currency mismatch");
        return new Money(a.Amount + b.Amount, a.Currency);
    }
}

public class BitArray
{
    private readonly ulong[] _bits;

    public BitArray(int capacity) => _bits = new ulong[(capacity + 63) / 64];

    // Indexer с get/set
    public bool this[int index]
    {
        get
        {
            if (index < 0 || index >= _bits.Length * 64) throw new IndexOutOfRangeException();
            return (_bits[index / 64] & (1UL << (index % 64))) != 0;
        }
        set
        {
            if (index < 0 || index >= _bits.Length * 64) throw new IndexOutOfRangeException();
            if (value) _bits[index / 64] |= 1UL << (index % 64);
            else _bits[index / 64] &= ~(1UL << (index % 64));
        }
    }

    // Indexer с параметрами
    public int this[int start, int count]
    {
        get
        {
            int result = 0;
            for (int i = 0; i < count; i++)
                if (this[start + i]) result |= 1 << i;
            return result;
        }
    }
}

