// Пользовательский тип с поддержкой Range/Index
public class CustomList<T>
{
    private T[] _items;
    public int Count { get; private set; }

    public T this[Index index] => _items[index.GetOffset(Count)];
    public CustomList<T> this[Range range]
    {
        get
        {
            var (offset, length) = range.GetOffsetAndLength(Count);
            var result = new CustomList<T> { _items = new T[length], Count = length };
            Array.Copy(_items, offset, result._items, 0, length);
            return result;
        }
    }
}

