unsafe void PointerBasics()
{
    int value = 42;
    int* ptr = &value;        // адрес переменной
    Console.WriteLine(*ptr);  // разыменование: 42

    *ptr = 100;               // изменение через указатель
    Console.WriteLine(value); // 100

    // Указатели на массивы (fixed)
    int[] arr = [1, 2, 3, 4, 5];
    fixed (int* p = arr)
    {
        for (int i = 0; i < arr.Length; i++)
            Console.WriteLine(p[i]); // p[i] == *(p + i)
    }
}

unsafe void StackAllocExample()
{
    // Выделение на стеке (быстро, автоматически освобождается)
    int* buffer = stackalloc int[100];

    for (int i = 0; i < 100; i++)
        buffer[i] = i * i;

    // Span<T> over stackalloc (без unsafe контекста!)
    Span<int> span = stackalloc int[100];
    span.Fill(42);
}

